-- saleinvoice_transaction (MergeTree)
CREATE TABLE datachangsiam.saleinvoice_transaction
(
    `doc_datetime` DateTime COMMENT 'วันที่/เวลา',
    `doc_no` String COMMENT 'เอกสารเลขที่',
    `creator_code` String COMMENT 'ผู้สร้างเอกสาร',
    `creator_name` String COMMENT 'ผู้สร้างเอกสาร',
    `status_cancel` String COMMENT 'สถานะยกเลิก Cancel=ยกเลิก',
    `pos_id` String COMMENT 'หมายเลขเครื่อง POS ถ้ามีแปลว่ามาจากขาย POS',
    `customer_code` String COMMENT 'รหัสลูกหนี้/ลูกค้า, ถ้าเป็นค่าว่าง คือลูกค้าทั่วไป',
    `customer_name` String COMMENT 'ชื่อลูกหนี้/ลูกค้า, ถ้าเป็นค่าว่าง คือลูกค้าทั่วไป',
    `sale_code` String COMMENT 'รหัสพนักงานขาย',
    `sale_name` String COMMENT 'ชื่อพนักงานขาย',
    `doc_type` String COMMENT 'ประเภทเอกสาร CREDIT=เงินเชื่อ, CASH=เงินสด',
    `due_date` DateTime COMMENT 'วันที่ครบกำหนด',
    `sum_point` Float64 COMMENT 'แต้ม',
    `total_value` Float64 COMMENT 'มูลค่าสินค้า',
    `total_discount` Float64 COMMENT 'มูลค่าส่วนลด',
    `total_before_vat` Float64 COMMENT 'ยอดก่อนภาษี',
    `total_vat_value` Float64 COMMENT 'ภาษีมูลค่าเพิ่ม',
    `total_after_vat` Float64 COMMENT 'มูลค่าหลังคิดภาษี',
    `total_except_vat` Float64 COMMENT 'มูลค่ายกเว้นภาษี',
    `total_amount` Float64 COMMENT 'มูลค่าสุทธิ',
    `remark` String COMMENT 'หมายเหตุ ทั้งหมด',
    `branch_code` String COMMENT 'รหัสสาขา',
    `branch_name` String COMMENT 'ชื่อสาขา',
    `department_code` String COMMENT 'รหัสแผนก',
    `department_name` String COMMENT 'ชื่อแผนก',
    `side_code` String COMMENT 'รหัสฝ่าย',
    `side_name` String COMMENT 'ชื่อฝ่าย',
    `project_code` String COMMENT 'รหัสโครงการ',
    `project_name` String COMMENT 'ชื่อโครงการ',
    `job_code` String COMMENT 'รหัสงาน',
    `job_name` String COMMENT 'ชื่องาน',
    `allocate_code` String COMMENT 'รหัสการจัดสรร',
    `allocate_name` String COMMENT 'ชื่อการจัดสรร',
    `billing_no_array` String COMMENT 'list เอกสารรับชำระ (รูปแบบ Json)',
    `sum_pay_money` Float64 COMMENT 'มูลค่ารับชำระ (กรณีขายเงินเชื่อ)',
    `status_payment` String COMMENT 'สถานะค้างชำระ Outstanding=ค้างชำระ, Partially Paid=ชำระบางส่วน, Fully Paid=ชำระครบแล้ว',
    `branch_sync` String COMMENT 'id ของร้าน/บริษัท',
    `branch_sync_name` String
)
ENGINE = MergeTree
PARTITION BY toYear(doc_datetime)
PRIMARY KEY (doc_no, branch_sync, branch_sync_name)
ORDER BY (doc_no, branch_sync, branch_sync_name, doc_datetime)
SETTINGS index_granularity = 8192, min_merge_bytes_to_use_direct_io = 10485760, merge_with_ttl_timeout = 86400, min_bytes_for_wide_part = 0, min_rows_for_wide_part = 0
COMMENT 'เอกสารขาย'

