    `ic_unit_name` String COMMENT 'ชื่อหน่วยนับ',
    `wh_code` String COMMENT 'รหัสคลัง',
    `wh_name` String COMMENT 'ชื่อคลัง',
    `shelf_code` String COMMENT 'รหัสที่เก็บ',
    `shelf_name` String COMMENT 'ชื่อที่เก็บ',
    `calc_type` String COMMENT 'ประเภทการคำนวณ',
    `qty` Float64 COMMENT 'จำนวน >0=จำนวนเข้า , <0=จำนวนออก',
    `cost` Float64 COMMENT 'ต้นทุนของเอกสาร',
    `amount` Float64 COMMENT 'มูลค่าตามเอกสาร',
    `item_brand_code` String COMMENT 'รหัสยี่ห้อสินค้า',
    `item_brand_name` String COMMENT 'ชื่อยี่ห้อสินค้า',
    `item_pattern_code` String COMMENT 'รหัสรูปแบบสินค้า',
    `item_pattern_name` String COMMENT 'ชื่อรูปแบบสินค้า',
    `item_design_code` String COMMENT 'รหัสรูปทรงสินค้า',
    `item_design_name` String COMMENT 'ชื่อรูปทรงสินค้า',
    `item_grade_code` String COMMENT 'รหัสเกรดสินค้า',
    `item_grade_name` String COMMENT 'ชื่อเกรดสินค้า',
    `item_model_code` String COMMENT 'รหัสรุ่นสินค้า',
    `item_model_name` String COMMENT 'ชื่อรุ่นสินค้า',
    `item_category_code` String COMMENT 'รหัสหมวดสินค้า',
    `item_category_name` String COMMENT 'ชื่อหมวดสินค้า',
    `item_class_code` String COMMENT 'รหัสระดับสินค้า',
    `item_class_name` String COMMENT 'ชื่อระดับสินค้า',
    `group_main_code` String COMMENT 'รหัสกลุ่มหลัก',
    `group_main_name` String COMMENT 'ชื่อกลุ่มหลัก',
    `group_sub_code` String COMMENT 'รหัสกลุ่มย่อย',
    `group_sub_name` String COMMENT 'ชื่อกลุ่มย่อย',
    `group_sub2_code` String COMMENT 'รหัสกลุ่มย่อย2',
    `group_sub2_name` String COMMENT 'ชื่อกลุ่มย่อย2',
    `branch_sync` String COMMENT 'id ของร้าน/บริษัท',
    `branch_sync_name` String
)
ENGINE = MergeTree
PARTITION BY toYYYYMM(doc_datetime)
PRIMARY KEY item_code
ORDER BY (item_code, wh_code, shelf_code, doc_datetime, doc_no, branch_sync, branch_sync_name)
SETTINGS index_granularity = 8192, min_merge_bytes_to_use_direct_io = 10485760, merge_with_ttl_timeout = 86400, min_bytes_for_wide_part = 0, min_rows_for_wide_part = 0
COMMENT 'เคลื่อนไหวสต็อก'

